use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let raw = state_read::get("urls")
            .or_else(|| state_read::get("subscriptions"))
            .unwrap_or_default();

        // The stored value is a whitespace-separated list of URLs
        // (URLs contain no whitespace).
        let urls: Vec<String> = raw
            .split_whitespace()
            .map(|s| s.to_string())
            .collect();

        // Contract: present(urls). With no subscriptions stored there is
        // nothing valid to return, so refuse rather than emit an empty list.
        if urls.is_empty() {
            panic!("no subscriptions found in state store");
        }

        SubscriptionList { urls }
    }
}

export!(Node);
