```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();

        for key in ["subscriptions", "urls", "feeds", "list"] {
            if let Some(raw) = state_read::get(key) {
                urls = raw
                    .split(|c: char| {
                        c.is_whitespace()
                            || c == ','
                            || c == '\u{1e}'
                            || c == '"'
                            || c == '\''
                            || c == '['
                            || c == ']'
                    })
                    .filter(|s| !s.is_empty())
                    .map(|s| s.to_string())
                    .collect();
                if !urls.is_empty() {
                    break;
                }
            }
        }

        SubscriptionList { urls }
    }
}

export!(Node);
